function fewestBracketSwaps(s: string): number {
  const balanced = (t: string): boolean => {
    let bal = 0;
    for (const c of t) {
      bal += c === "[" ? 1 : -1;
      if (bal < 0) return false;
    }
    return true;
  };
  const seen = new Set<string>([s]);
  let level = [s];
  for (let d = 0; ; d++) {
    const next: string[] = [];
    for (const t of level) {
      if (balanced(t)) return d;
      for (let i = 0; i < t.length; i++) {
        for (let j = i + 1; j < t.length; j++) {
          if (t[i] === t[j]) continue;
          const u = t.slice(0, i) + t[j] + t.slice(i + 1, j) + t[i] + t.slice(j + 1);
          if (!seen.has(u)) {
            seen.add(u);
            next.push(u);
          }
        }
      }
    }
    level = next;
  }
}

