            for c in t:
                bal += 1 if c == "[" else -1
                if bal < 0:
                    return False
            return True

        seen = {s}
        level = [s]
        d = 0
        while True:
            nxt = []
            for t in level:
                if balanced(t):
                    return d
                for i in range(len(t)):
                    for j in range(i + 1, len(t)):
                        if t[i] == t[j]:
                            continue
                        u = t[:i] + t[j] + t[i + 1:j] + t[i] + t[j + 1:]
                        if u not in seen:
                            seen.add(u)
                            nxt.append(u)
            level = nxt
            d += 1

