function fewestBracketSwaps(s: string): number {
  let open = 0, unmatched = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] === "[") open++;
    else if (open > 0) open--;
    else unmatched++;
  }
  return Math.floor((unmatched + 1) / 2);
}

